#!/usr/bin/env python3
"""Writes the generated region of PROOF_canon.bend: the case splits on the
16 code lengths (0 to 15) that are too long to write by hand.

  * cn.incshape: hf.inc on a list of 16 counts, one case per length (and
    one for a length of 16 or more, which is not counted);
  * cn.cgo, cn.counts_eq: hf.counts is the list of canon_count(ls, n);
  * cn.next_cases, cn.next_get, cn.next_len: hf.next of those 16 counts,
    entry by entry, is canon_next.

  python3 gen/canon.py           rewrite the region between
                                 "# BEGIN GENERATED by gen/canon.py"
                                 and "# END GENERATED by gen/canon.py"
  python3 gen/canon.py --check   only check that it is up to date
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.join(HERE, "..")
L = "List<&2, U32>"


def con(items):
    s = "Nil{}"
    for x in reversed(items):
        s = "Con{%s, %s}" % (x, s)
    return s


def ind(d):
    return "  " * d


def region():
    list16 = con(["Laws.canon_count(ls, %dn)" % k for k in range(16)])
    a = ["a%d" % k for k in range(16)]
    cona = con(a)
    aparams = ", ".join("+a%d: U32" % k for k in range(16))
    out = []

    rhs = con(["Laws.canon_step(Nat.is_eq(n, %dn), a%d)" % (k, k) for k in range(16)])
    out.append("# one more at length n, for each n (a symbol of length 16 or more is")
    out.append("# not counted)")
    out.append("def cn.incshape(+n: Nat, %s) -> {H.hf.inc(%s, n) == %s : %s}:" % (aparams, cona, rhs, L))
    var, d = "n", 1
    for k in range(16):
        out.append(ind(d) + "match %s:" % var)
        out.append(ind(d + 1) + "case 0n:")
        out.append(ind(d + 2) + "{==}")
        nv = "n%d" % (k + 1)
        out.append(ind(d + 1) + "case 1n+ +%s:" % nv)
        var, d = nv, d + 2
    out.append(ind(d) + "{==}")
    out.append("")

    lhs = "H.hf.counts.go(ls, %s)" % cona
    rhs = con(["Laws.canon_count.go(ls, %dn, a%d)" % (k, k) for k in range(16)])
    steps = ["Laws.canon_step(Nat.is_eq(U32.to_nat(h), %dn), a%d)" % (k, k) for k in range(16)]
    rhs_t = con(["Laws.canon_count.go(t, %dn, %s)" % (k, steps[k]) for k in range(16)])
    out.append("# the counts, from any 16 starting values")
    out.append("def cn.cgo(+ls: %s, %s) -> {%s == %s : %s}:" % (L, aparams, lhs, rhs, L))
    out.append("  match ls:")
    out.append("    case Nil{}:")
    out.append("      {==}")
    out.append("    case Con{+h, t}:")
    out.append("      %%Equal.sym(%s, H.hf.inc(%s, U32.to_nat(h)), %s, cn.incshape(U32.to_nat(h), %s)) : {H.hf.counts.go(t, _) == %s : %s}" % (L, cona, con(steps), ", ".join(a), rhs_t, L))
    out.append("      cn.cgo(t, %s)" % ", ".join(steps))
    out.append("")

    out.append("# counting by length: hf.counts is bl_count[0..15]")
    out.append("def cn.counts_eq(+ls: %s) -> {H.hf.counts(ls) == %s : %s}:" % (L, list16, L))
    out.append("  cn.cgo(ls, %s)" % ", ".join(["0"] * 16))
    out.append("")

    out.append("# next_code: the first codes of the 16 counts, entry by entry")
    out.append("def cn.next_cases(+ls: %s, +q: Nat, +hq: {Nat.is_le(1n+q, 15n) == True{} : Bool}) -> {H.hf.get(H.hf.next(%s), 1n+q) == Laws.canon_next(ls, 1n+q) : U32}:" % (L, list16))
    var, d = "q", 1
    for k in range(15):
        out.append(ind(d) + "match %s:" % var)
        out.append(ind(d + 1) + "case 0n:")
        out.append(ind(d + 2) + "{==}")
        nv = "q%d" % (k + 1)
        out.append(ind(d + 1) + "case 1n+ +%s:" % nv)
        var, d = nv, d + 2
    big = "1n+" * 16 + var
    out.append(ind(d) + "Empty.absurd({H.hf.get(H.hf.next(%s), %s) == Laws.canon_next(ls, %s) : U32}, cn.ft(hq))" % (list16, big, big))
    out.append("")

    out.append("def cn.next_get(+ls: %s, +q: Nat, +hq: {Nat.is_le(1n+q, 15n) == True{} : Bool}) -> {H.hf.get(H.hf.next(H.hf.counts(ls)), 1n+q) == Laws.canon_next(ls, 1n+q) : U32}:" % L)
    out.append("  %%Equal.sym(%s, H.hf.counts(ls), %s, cn.counts_eq(ls)) : {H.hf.get(H.hf.next(_), 1n+q) == Laws.canon_next(ls, 1n+q) : U32}" % (L, list16))
    out.append("  cn.next_cases(ls, q, hq)")
    out.append("")
    out.append("def cn.next_len(+ls: %s) -> {List.length(&2, U32, H.hf.next(H.hf.counts(ls))) == 16n : Nat}:" % L)
    out.append("  %%Equal.sym(%s, H.hf.counts(ls), %s, cn.counts_eq(ls)) : {List.length(&2, U32, H.hf.next(_)) == 16n : Nat}" % (L, list16))
    out.append("  {==}")
    return "\n".join(out) + "\n"


def main():
    path = os.path.join(PKG, "PROOF_canon.bend")
    with open(path, encoding="utf-8", newline="") as f:
        src = f.read()
    begin = "# BEGIN GENERATED by gen/canon.py\n"
    end = "# END GENERATED by gen/canon.py\n"
    i = src.index(begin) + len(begin)
    j = src.index(end, i)
    new = src[:i] + region() + src[j:]
    if "--check" in sys.argv[1:]:
        if new != src:
            print("PROOF_canon.bend differs from what gen/canon.py generates")
            sys.exit(1)
        print("PROOF_canon.bend is up to date")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)


if __name__ == "__main__":
    main()
